// Main.cpp — Xbox 360 entry point for the NEW j2x-converted Minecraft Alpha.
//
// REFERENCE TEMPLATE for the Xbox-project integration (Step 1). It is NOT part of the converter
// output and is NOT compiled by the j2x build — drop it into the Xbox VS project alongside the
// platform layer. Based on the OLD port's proven Main.cpp (../MinecraftAlpha/Main.cpp), with two
// changes for the new codebase:
//   1) ordered static init is now ONE call -- j2x_initAll() (j2x_init.h, generated by the
//      converter) -- instead of ~13 hand-listed initStatics() calls. It runs every class's Java
//      static{} blocks + static field inits in dependency order (see j2x_init.cpp / pipeline
//      _STATIC_INIT_ORDER). If a boot crash traces to a null static, fix the order THERE.
//   2) the new Minecraft has NO default ctor -- use the parameterized one:
//      Minecraft(Component*, Canvas*, MinecraftApplet*, int width, int height, bool fullscreen).
//
// PLATFORM DEPENDENCIES (carried over from the old port, reused as-is): Common.h (D3D9 device +
// globals), Shaders.h (HLSL pipeline -- Xenos has no fixed function), Tesselator.h, Textures.h.
// NOTE: rendering will only actually draw once the GL->D3D9 emulator (Step 2) backs the GL11 the
// new game code calls; until then expect a clear-only frame. EH/exceptions: the new output uses
// try/catch; build with /EHsc (or strip — old port compiled with EH off, catch blocks dead).

#include "stdafx.h"
#include "Common.h"
#include "Shaders.h"
#include "GL11.h"
#include "Tesselator.h"
#include "Textures.h"
#include "Minecraft.h"
#include "j2x_init.h"        // <-- generated: void j2x_initAll();

// Globals (defined once here; declared extern in Common.h)
IDirect3D9*        g_pD3D           = NULL;
IDirect3DDevice9*  g_pd3dDevice     = NULL;
IDirect3DTexture9* g_terrainTexture = NULL;
IDirect3DTexture9* g_guiTexture     = NULL;
IDirect3DTexture9* g_charTexture    = NULL;
IDirect3DTexture9* g_defaultTexture = NULL;

Minecraft* g_minecraft = NULL;

static bool InitD3D() {
    g_pD3D = Direct3DCreate9(D3D_SDK_VERSION);
    if (!g_pD3D) return false;
    D3DPRESENT_PARAMETERS d3dpp;
    ZeroMemory(&d3dpp, sizeof(d3dpp));
    d3dpp.BackBufferWidth            = SCREEN_WIDTH;
    d3dpp.BackBufferHeight           = SCREEN_HEIGHT;
    d3dpp.BackBufferFormat           = D3DFMT_X8R8G8B8;
    d3dpp.BackBufferCount            = 1;
    d3dpp.MultiSampleType            = D3DMULTISAMPLE_NONE;
    d3dpp.SwapEffect                 = D3DSWAPEFFECT_DISCARD;
    d3dpp.EnableAutoDepthStencil     = TRUE;
    d3dpp.AutoDepthStencilFormat     = D3DFMT_D24S8;
    d3dpp.FullScreen_RefreshRateInHz = 60;
    d3dpp.PresentationInterval       = D3DPRESENT_INTERVAL_IMMEDIATE;
    HRESULT hr = g_pD3D->CreateDevice(0, D3DDEVTYPE_HAL, NULL,
        D3DCREATE_HARDWARE_VERTEXPROCESSING, &d3dpp, &g_pd3dDevice);
    return SUCCEEDED(hr);
}

static void ApplyDefaultRenderState() {
    g_pd3dDevice->SetRenderState(D3DRS_ZENABLE, TRUE);
    g_pd3dDevice->SetRenderState(D3DRS_ZWRITEENABLE, TRUE);
    g_pd3dDevice->SetRenderState(D3DRS_ZFUNC, D3DCMP_LESSEQUAL);
    g_pd3dDevice->SetRenderState(D3DRS_CULLMODE, D3DCULL_CW);
    g_pd3dDevice->SetRenderState(D3DRS_ALPHABLENDENABLE, FALSE);
    g_pd3dDevice->SetSamplerState(0, D3DSAMP_MINFILTER, D3DTEXF_POINT);   // pixel-art: nearest
    g_pd3dDevice->SetSamplerState(0, D3DSAMP_MAGFILTER, D3DTEXF_POINT);
    g_pd3dDevice->SetSamplerState(0, D3DSAMP_MIPFILTER, D3DTEXF_NONE);
}

void __cdecl main() {
    if (!InitD3D()) { DbgPrintF("[BOOT] D3D init failed\n"); return; }
    ApplyDefaultRenderState();

    if (!Shaders::init()) { DbgPrintF("[BOOT] shader compile failed\n"); return; }

    // GL emulator init: seed the MODELVIEW/PROJECTION matrix stacks with identity. Without this the
    // stacks are empty std::vectors and the very first glLoadIdentity()/glOrtho() in Minecraft::
    // loadScreen() does back() on an empty vector -> crash (the black-screen-after-fontRenderer hang).
    GL11::glInit();

    Textures::init();
    Textures::loadAll();
    g_terrainTexture = Textures::getById(Textures::load("game:\\Content\\terrain.png"));
    g_guiTexture     = Textures::getById(Textures::load("game:\\Content\\gui\\gui.png"));
    g_charTexture    = Textures::getById(Textures::load("game:\\Content\\mob\\char.png"));
    g_defaultTexture = Textures::getById(Textures::load("game:\\Content\\default.png"));

    // Run EVERY class's Java static{} blocks + static field initializers, in dependency order.
    // (Replaces the old port's ~13 hand-listed initStatics() calls.) MUST run before any game code:
    // skip it and every Block / Item / registry / enum singleton is null -> first use jumps a null
    // vtable (the static-init-order crash class the converter now prevents by construction).
    j2x_initAll();

    // The new Minecraft has no default ctor: pass the display size the AWT ctor would have set.
    // (Component/Canvas/Applet are the AWT host -- null on console.) run() does the remaining init
    // (game settings, render engine, font, main menu) and owns the tick + render + Present loop.
    g_minecraft = new Minecraft(NULL, NULL, NULL, SCREEN_WIDTH, SCREEN_HEIGHT, false);
    g_pd3dDevice->BeginScene();   // open the first scene; Display::swapBuffers/update End+Present+Begin each frame
    g_minecraft->run();

    Shaders::shutdown();
    Textures::shutdown();
    if (g_pd3dDevice) g_pd3dDevice->Release();
    if (g_pD3D)       g_pD3D->Release();
}
